#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Cloud preflight gate for the LoomLoom v4 template.

Runs as a Code node before the four paid reviews and the model node. It checks
the input contract only: packet shape, freshness, sources, units, market-cap
reconciliation, balance-sheet presence, source tiers, and model-assumption
drivers. It has no network access and never fetches a filing or a quote.

Outputs:
    ready     boolean  -- false when any error-severity finding exists
    findings  array    -- [{code, severity, path, message}]
    summary   object   -- {ticker, asOf, checks, errors, warnings, ready}

The same rules exist in the local ``preflight.mjs``. The cloud copy is a
fail-fast gate; the local copy remains the development and offline reference.
"""

from __future__ import annotations

import datetime
import json
import re
from typing import Any, Dict, List, Optional

TICKER_RE = re.compile(r"^[A-Z][A-Z0-9.-]{0,9}$")
TIERS = ("S", "A", "B", "C")
QUAL_GROUPS = ("businessModel", "moatEvidence", "managementCulture", "capitalAllocation", "riskFactors", "contraryEvidence", "unknowns")
FACT_GROUPS = QUAL_GROUPS[:6]
SCENARIO_FIELDS = (
    "years",
    "revenueGrowth",
    "ebitMargin",
    "taxRate",
    "daPctRevenue",
    "capexPctRevenue",
    "nwcPctRevenue",
    "interestRateOnDebt",
    "debtRepaymentPct",
    "wacc",
    "terminalMethod",
)


def _issue(code: str, severity: str, path: str, message: str) -> Dict[str, str]:
    return {"code": code, "severity": severity, "path": path, "message": message}


def _num(value: Any) -> Optional[float]:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip().replace(",", "").replace("$", ""))
        except ValueError:
            return None
    return None


def _text(value: Any) -> str:
    return str(value or "").strip()


def _obj(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _parse_json(value: Any, label: str) -> Dict[str, Any]:
    if isinstance(value, dict):
        return value
    raw = _text(value)
    if not raw:
        raise ValueError("%s is empty" % label)
    parsed = json.loads(raw)
    if not isinstance(parsed, dict):
        raise ValueError("%s must be a JSON object" % label)
    return parsed


def _date(value: Any) -> Optional[datetime.date]:
    raw = _text(value)
    if not re.match(r"^\d{4}-\d{2}-\d{2}", raw):
        return None
    try:
        return datetime.date.fromisoformat(raw[:10])
    except ValueError:
        return None


def _age_days(value: Any, reference: datetime.date) -> Optional[int]:
    parsed = _date(value)
    if parsed is None:
        return None
    return (reference - parsed).days


class Preflight:
    def __init__(self, reference: datetime.date):
        self.reference = reference
        self.findings: List[Dict[str, str]] = []
        self.checks = 0

    def add(self, code: str, severity: str, path: str, message: str) -> None:
        self.checks += 1
        self.findings.append(_issue(code, severity, path, message))

    def require(self, condition: bool, code: str, path: str, message: str) -> bool:
        self.checks += 1
        if not condition:
            self.findings.append(_issue(code, "error", path, message))
            return False
        return True

    def warn(self, condition: bool, code: str, path: str, message: str) -> bool:
        self.checks += 1
        if not condition:
            self.findings.append(_issue(code, "warning", path, message))
            return False
        return True


def _check_identity(pre: Preflight, identity: Dict[str, Any]) -> str:
    ticker = _text(identity.get("ticker")).upper()
    pre.require(bool(TICKER_RE.match(ticker)), "INVALID_TICKER", "identityPacket.ticker", "ticker must match ^[A-Z][A-Z0-9.-]{0,9}$")
    pre.require(bool(_text(identity.get("companyName"))), "COMPANY_NAME_MISSING", "identityPacket.companyName", "companyName is required")
    pre.require(bool(_text(identity.get("fiscalPeriod"))), "FISCAL_PERIOD_MISSING", "identityPacket.fiscalPeriod", "fiscalPeriod is required")

    text_date = _date(identity.get("dataAsOf"))
    if not pre.require(text_date is not None, "INVALID_DATE", "identityPacket.dataAsOf", "dataAsOf must be a valid YYYY-MM-DD date"):
        return ticker
    age = (pre.reference - text_date).days
    pre.require(age <= 45, "STALE_DATA", "identityPacket.dataAsOf", "dataAsOf is more than 45 days old")
    pre.require(age >= -1, "FUTURE_DATA", "identityPacket.dataAsOf", "dataAsOf is later than the as-of date")

    sources = identity.get("sources") if isinstance(identity.get("sources"), list) else []
    valid_sources = [source for source in sources if isinstance(source, str) and source.startswith("https://")]
    pre.require(bool(valid_sources), "SOURCES_MISSING", "identityPacket.sources", "at least one HTTPS source URL is required")
    return ticker


def _check_financial(pre: Preflight, financial: Dict[str, Any]) -> Optional[float]:
    pre.require(bool(financial), "FINANCIAL_PACKET_MISSING", "financialPacket", "financialPacket must be an object")
    if not financial:
        return None

    units = _text(financial.get("units"))
    pre.warn(units.startswith(("USD", "CNY", "EUR", "GBP", "JPY", "HKD")), "UNITS_MISSING", "financialPacket.units", "declare units, e.g. 'USD millions'")

    market = _obj(financial.get("marketSnapshot"))
    pre.require(bool(market), "MARKET_SNAPSHOT_MISSING", "financialPacket.marketSnapshot", "marketSnapshot is required")
    if not market:
        return None

    price = _num(market.get("price"))
    pre.require(price is not None and price > 0, "INVALID_PRICE", "financialPacket.marketSnapshot.price", "price must be a positive number")

    currency = _text(market.get("currency"))
    unit_currency = units[:3] if units[:3].isalpha() and units[:3].isupper() else ""
    pre.require(bool(currency) or bool(unit_currency), "CURRENCY_MISSING", "financialPacket.marketSnapshot.currency", "currency is required, or derive it from financialPacket.units")
    if currency and unit_currency:
        pre.require(currency == unit_currency, "CURRENCY_MISMATCH", "financialPacket.marketSnapshot.currency", "currency does not match financialPacket.units")

    quote_date = _date(market.get("asOf"))
    if pre.require(quote_date is not None, "INVALID_DATE", "financialPacket.marketSnapshot.asOf", "quote asOf must be a valid date"):
        age = (pre.reference - quote_date).days
        pre.require(age <= 7, "STALE_PRICE", "financialPacket.marketSnapshot.asOf", "quote is more than 7 days old")
        pre.require(age >= -1, "FUTURE_DATA", "financialPacket.marketSnapshot.asOf", "quote asOf is later than the as-of date")

    pe = market.get("pe")
    if pe is None:
        unknowns = financial.get("unknowns") if isinstance(financial.get("unknowns"), list) else []
        pre.require(
            any(re.search(r"\b(pe|p\/e|earnings|loss)\b", str(item), re.I) for item in unknowns),
            "PE_UNKNOWN_UNEXPLAINED",
            "financialPacket.unknowns",
            "a null PE must be explained in financialPacket.unknowns",
        )
    else:
        parsed_pe = _num(pe)
        pre.require(parsed_pe is not None, "INVALID_PE", "financialPacket.marketSnapshot.pe", "PE must be a number or null")
        if parsed_pe is not None:
            pre.warn(parsed_pe > 0, "NON_POSITIVE_PE", "financialPacket.marketSnapshot.pe", "PE is zero or negative; confirm it is meaningful")

    history = _obj(financial.get("annualHistory"))
    periods = history.get("fiscalYearEnd") if isinstance(history.get("fiscalYearEnd"), list) else []
    valid_periods = [_date(period) for period in periods]
    pre.require(len(periods) >= 3 and all(valid_periods), "INVALID_FISCAL_PERIODS", "financialPacket.annualHistory.fiscalYearEnd", "at least three valid fiscal year end dates are required")
    for key in ("revenue", "netIncome", "freeCashFlow"):
        values = history.get(key)
        if pre.require(isinstance(values, list), "MISSING_ANNUAL_SERIES", "financialPacket.annualHistory.%s" % key, "annual series is required"):
            pre.require(len(values) == len(periods), "HISTORY_LENGTH_MISMATCH", "financialPacket.annualHistory.%s" % key, "array length must match fiscalYearEnd")
    revenue = history.get("revenue") if isinstance(history.get("revenue"), list) else []
    pre.require(bool(revenue) and _num(revenue[-1]) is not None and _num(revenue[-1]) > 0, "INVALID_STARTING_REVENUE", "financialPacket.annualHistory.revenue", "latest fiscal-year revenue must be positive")

    balance = _obj(financial.get("balanceSheet"))
    if not balance:
        balance = financial
    shares = _num(balance.get("sharesOutstanding") or financial.get("sharesOutstanding") or market.get("sharesOutstanding"))
    pre.require(shares is not None and shares > 0, "SHARES_MISSING", "financialPacket.balanceSheet.sharesOutstanding", "diluted shares are required for per-share and market-cap checks")

    market_cap = _num(market.get("marketCapUsd"))
    if not pre.require(market_cap is not None and market_cap > 0, "MARKET_CAP_MISSING", "financialPacket.marketSnapshot.marketCapUsd", "marketCapUsd is required for reconciliation (same units as financialPacket)"):
        market_cap = None
    if market_cap is not None and price is not None and shares is not None and shares > 0:
        delta = abs(price * shares - market_cap) / market_cap
        pre.require(delta <= 0.02, "MARKET_CAP_MISMATCH", "financialPacket.marketSnapshot.marketCapUsd", "price * shares differs from marketCapUsd by %.2f%%, above the 2%% tolerance" % (delta * 100.0))

    equity = _num(balance.get("equity") or balance.get("totalEquity") or balance.get("shareholdersEquity") or balance.get("stockholdersEquity"))
    pre.require(equity is not None, "BALANCE_SHEET_EQUITY_MISSING", "financialPacket.balanceSheet.equity", "opening shareholders' equity is required")
    nwc = _num(balance.get("nwc") or balance.get("netWorkingCapital"))
    current_assets = _num(balance.get("currentAssets"))
    current_liabilities = _num(balance.get("currentLiabilities"))
    if nwc is None:
        pre.require(current_assets is not None and current_liabilities is not None, "BALANCE_SHEET_NWC_MISSING", "financialPacket.balanceSheet.netWorkingCapital", "supply netWorkingCapital, or currentAssets and currentLiabilities")
        if current_assets is not None and current_liabilities is not None:
            short_debt = _num(balance.get("shortTermDebt")) or 0.0
            nwc = (current_assets - (_num(balance.get("cash")) or 0.0)) - (current_liabilities - short_debt)
    net_ppe = _num(balance.get("netPPE") or balance.get("ppeNet") or balance.get("propertyPlantAndEquipmentNet"))
    total_assets = _num(balance.get("totalAssets"))
    pre.require(net_ppe is not None or total_assets is not None, "BALANCE_SHEET_PPE_MISSING", "financialPacket.balanceSheet.netPPE", "supply netPPE or totalAssets")

    if equity is not None and nwc is not None and (net_ppe is not None or total_assets is not None):
        cash = _num(balance.get("cash")) or 0.0
        debt = _num(balance.get("totalDebt") or balance.get("debt")) or 0.0
        if debt == 0.0:
            debt = (_num(balance.get("shortTermDebt")) or 0.0) + (_num(balance.get("longTermDebt")) or 0.0)
        other_assets = _num(balance.get("otherAssets")) or 0.0
        other_liabilities = _num(balance.get("otherLiabilities")) or 0.0
        if net_ppe is None and total_assets is not None:
            net_ppe = total_assets - cash - nwc - other_assets
        assets = cash + nwc + net_ppe + other_assets
        liabilities_and_equity = debt + other_liabilities + equity
        tolerance = max(1.0, abs(assets) * 0.0001)
        gap = abs(assets - liabilities_and_equity)
        pre.require(gap <= tolerance, "OPENING_BALANCE_SHEET_UNBALANCED", "financialPacket.balanceSheet", "assets %.1f vs liabilities + equity %.1f (gap %.1f, tolerance %.1f)" % (assets, liabilities_and_equity, gap, tolerance))

    return price


def _check_qualitative(pre: Preflight, qualitative: Dict[str, Any]) -> None:
    for group in QUAL_GROUPS:
        pre.require(isinstance(qualitative.get(group), list), "QUALITATIVE_GROUP_MISSING", "qualitativePacket.%s" % group, "group must be an array")
    for group in FACT_GROUPS:
        items = qualitative.get(group)
        if not isinstance(items, list):
            continue
        for index, item in enumerate(items):
            path = "qualitativePacket.%s[%d]" % (group, index)
            if not pre.require(isinstance(item, dict), "QUALITATIVE_FACT_INVALID", path, "fact must be an object"):
                continue
            pre.require(bool(_text(item.get("fact"))), "FACT_MISSING", path + ".fact", "fact text is required")
            source = _text(item.get("source"))
            pre.require(source.startswith("https://"), "FACT_SOURCE_INVALID", path + ".source", "source must be an HTTPS URL")
            fact_date = _date(item.get("date"))
            if pre.require(fact_date is not None, "FACT_DATE_INVALID", path + ".date", "date must be a valid YYYY-MM-DD"):
                age = (pre.reference - fact_date).days
                pre.warn(age <= 550, "FACT_STALE", path + ".date", "qualitative fact is older than 550 days")
                pre.require(age >= -1, "FUTURE_DATA", path + ".date", "fact date is later than the as-of date")
            tier = _text(item.get("sourceTier") or item.get("tier")).upper()
            if not tier:
                pre.warn(False, "SOURCE_TIER_MISSING", path + ".sourceTier", "add sourceTier S/A/B/C so tier gating is explicit")
            elif tier not in TIERS:
                pre.require(False, "SOURCE_TIER_INVALID", path + ".sourceTier", "sourceTier must be one of S, A, B, C")
            elif tier == "C":
                pre.require(False, "TIER_C_NOT_EVIDENCE", path + ".sourceTier", "C-tier sources (forums/blogs/Wikipedia) cannot carry evidence")


def _check_scenario(pre: Preflight, name: str, scenario: Dict[str, Any]) -> None:
    prefix = "modelAssumptions.scenarios.%s" % name
    years = _num(scenario.get("years"))
    pre.require(years is not None and float(int(years)) == years and 1 <= int(years) <= 10, "SCENARIO_YEARS_INVALID", prefix + ".years", "years must be an integer 1-10")
    year_count = int(years) if years is not None and float(int(years)) == years and 1 <= int(years) <= 10 else None

    for field in SCENARIO_FIELDS:
        pre.require(scenario.get(field) is not None, "SCENARIO_DRIVER_MISSING", "%s.%s" % (prefix, field), "required driver is missing; there are no defaults")

    for field in ("revenueGrowth", "ebitMargin"):
        value = scenario.get(field)
        if isinstance(value, list):
            if year_count is not None:
                pre.require(len(value) == year_count, "SCENARIO_SERIES_LENGTH", "%s.%s" % (prefix, field), "array length must equal years")
            for index, item in enumerate(value):
                pre.require(_num(item) is not None, "SCENARIO_SERIES_INVALID", "%s.%s[%d]" % (prefix, field, index), "must be a finite number")
        elif value is not None:
            pre.require(_num(value) is not None, "SCENARIO_SERIES_INVALID", "%s.%s" % (prefix, field), "must be a number or an array of numbers")

    ranges = {
        "taxRate": (0.0, 0.6),
        "daPctRevenue": (0.0, 1.0),
        "capexPctRevenue": (0.0, 2.0),
        "nwcPctRevenue": (-1.0, 2.0),
        "interestRateOnDebt": (0.0, 0.5),
        "debtRepaymentPct": (0.0, 1.0),
        "wacc": (0.005, 0.5),
    }
    for field, (low, high) in ranges.items():
        value = _num(scenario.get(field))
        if value is not None:
            pre.require(low <= value <= high, "SCENARIO_DRIVER_RANGE", "%s.%s" % (prefix, field), "must be between %s and %s" % (low, high))

    method = _text(scenario.get("terminalMethod"))
    pre.require(method in ("perpetuity", "exitMultiple"), "SCENARIO_TERMINAL_METHOD", prefix + ".terminalMethod", "must be 'perpetuity' or 'exitMultiple'")
    wacc = _num(scenario.get("wacc"))
    if method == "perpetuity":
        growth = _num(scenario.get("terminalGrowth"))
        if pre.require(growth is not None and -0.5 < growth < 0.25, "SCENARIO_TERMINAL_GROWTH", prefix + ".terminalGrowth", "terminalGrowth must be between -0.5 and 0.25"):
            pre.require(wacc is not None and wacc > growth + 0.005, "SCENARIO_WACC_NOT_ABOVE_TERMINAL", prefix + ".wacc", "WACC must exceed terminalGrowth by at least 0.5 percentage points")
    elif method == "exitMultiple":
        multiple = _num(scenario.get("exitMultiple") or scenario.get("terminalMultiple"))
        pre.require(multiple is not None and multiple > 0, "SCENARIO_EXIT_MULTIPLE", prefix + ".exitMultiple", "exitMultiple must be positive")
        basis = _text(scenario.get("exitMultipleBasis") or "ebit")
        pre.require(basis in ("ebit", "ebitda"), "SCENARIO_EXIT_BASIS", prefix + ".exitMultipleBasis", "must be 'ebit' or 'ebitda'")
    if scenario.get("startingRevenue") is not None:
        starting = _num(scenario.get("startingRevenue"))
        pre.require(starting is not None and starting > 0, "SCENARIO_STARTING_REVENUE", prefix + ".startingRevenue", "must be positive")


def _check_assumptions(pre: Preflight, assumptions: Dict[str, Any]) -> None:
    scenarios = assumptions.get("scenarios")
    pre.require(isinstance(scenarios, dict) and bool(scenarios), "SCENARIOS_MISSING", "modelAssumptions.scenarios", "at least one scenario is required")
    if not isinstance(scenarios, dict):
        return
    for name, scenario in scenarios.items():
        if pre.require(isinstance(scenario, dict), "SCENARIO_INVALID", "modelAssumptions.scenarios.%s" % name, "scenario must be an object"):
            _check_scenario(pre, str(name), scenario)

    base = _text(assumptions.get("baseScenario") or "base")
    pre.require(base in scenarios, "BASE_SCENARIO_MISSING", "modelAssumptions.baseScenario", "baseScenario must name a supplied scenario")
    pre.warn(isinstance(assumptions.get("sources"), list) and bool(assumptions.get("sources")), "ASSUMPTIONS_WITHOUT_SOURCES", "modelAssumptions.sources", "add sources[] naming the owner and date of each driver")
    as_of = assumptions.get("asOf")
    if as_of is not None:
        pre.require(_date(as_of) is not None, "INVALID_DATE", "modelAssumptions.asOf", "asOf must be a valid date")


def _result(pre: Preflight, ticker: str) -> Dict[str, Any]:
    errors = [finding for finding in pre.findings if finding["severity"] == "error"]
    warnings = [finding for finding in pre.findings if finding["severity"] == "warning"]
    return {
        "ready": len(errors) == 0,
        "findings": pre.findings,
        "summary": {
            "ticker": ticker,
            "asOf": pre.reference.isoformat(),
            "checks": pre.checks,
            "errors": len(errors),
            "warnings": len(warnings),
            "ready": len(errors) == 0,
        },
    }


def main(inputs: Any) -> Dict[str, Any]:
    """LoomLoom Code node entrypoint."""
    if not isinstance(inputs, dict):
        inputs = {}
    raw_as_of = _text(inputs.get("asOf"))
    reference = _date(raw_as_of)
    assumptions: Dict[str, Any] = {}
    try:
        assumptions = _parse_json(inputs.get("assumptions"), "modelAssumptions")
    except ValueError:
        assumptions = {}
    if reference is None:
        reference = _date(assumptions.get("asOf")) or datetime.date.today()
    pre = Preflight(reference)

    try:
        packets = _parse_json(inputs.get("tickerPacket"), "tickerPacket")
    except ValueError as exc:
        pre.add("PACKET_NOT_JSON", "error", "tickerPacket", str(exc))
        return _result(pre, "")
    if not pre.require(bool(packets), "PACKET_EMPTY", "tickerPacket", "tickerPacket must contain identityPacket, financialPacket and qualitativePacket"):
        return _result(pre, "")

    identity = _obj(packets.get("identityPacket"))
    financial = _obj(packets.get("financialPacket"))
    qualitative = _obj(packets.get("qualitativePacket"))
    if not pre.require(bool(identity) and bool(financial) and bool(qualitative), "PACKETS_INCOMPLETE", "tickerPacket", "all three packets are required"):
        return _result(pre, _text(identity.get("ticker")).upper())

    ticker = _check_identity(pre, identity)
    _check_financial(pre, financial)
    _check_qualitative(pre, qualitative)

    if not assumptions:
        pre.add("ASSUMPTIONS_NOT_JSON", "error", "modelAssumptions", "modelAssumptions must be a JSON object")
    else:
        _check_assumptions(pre, assumptions)

    if raw_as_of and _date(raw_as_of) is None:
        pre.add("INVALID_AS_OF", "error", "asOf", "asOf must be a valid YYYY-MM-DD date")

    return _result(pre, ticker)


if __name__ == "__main__":
    import sys

    payload = json.load(sys.stdin)
    json.dump(main(payload), sys.stdout, ensure_ascii=False)

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Judge one round of the four reviews inside a Loop.

The body produces four review JSON strings. This Code node checks structure and
evidence resolvability. On the first failed round it returns `continue`; on the
final allowed round it accepts the candidate so the outer audit can reject it
explicitly instead of publishing nothing.
"""

from __future__ import annotations

import json
import math
import re
from typing import Any, Dict, List, Optional, Tuple

DIMENSIONS = ("business", "moat", "financial", "valuation")
INPUT_KEYS = {"business": "business", "moat": "management", "financial": "financial", "valuation": "valuation"}
PACKET_PREFIX = {"business": "qualitativePacket", "moat": "qualitativePacket", "financial": "financialPacket", "valuation": "financialPacket"}
PACKET_PREFIXES = ("identityPacket", "financialPacket", "qualitativePacket")
SCORE_FIELDS = {
    "business": ("business_model_score", "understandability_score"),
    "moat": ("moat_score", "management_culture_score", "capital_allocation_score"),
    "financial": ("financial_quality_score", "cash_flow_quality_score", "balance_sheet_score"),
    "valuation": ("valuation_score", "margin_of_safety_score"),
}


def _obj(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _text(value: Any) -> str:
    return str(value if value is not None else "").strip()


def _num(value: Any) -> Optional[float]:
    if value is None or isinstance(value, bool):
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _atomic(value: Any) -> bool:
    return value is None or isinstance(value, (str, int, float, bool))


def _same(left: Any, right: Any) -> bool:
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return math.isclose(float(left), float(right), rel_tol=1e-6, abs_tol=1e-6)
    return json.dumps(left, sort_keys=True, ensure_ascii=False) == json.dumps(right, sort_keys=True, ensure_ascii=False)


def _parse(value: Any, label: str) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
    if isinstance(value, dict):
        return value, None
    raw = _text(value)
    if not raw:
        return None, "%s is empty" % label
    fenced = re.search(r"```(?:json)?\s*(\{.*\})\s*```", raw, re.S | re.I)
    if fenced:
        raw = fenced.group(1)
    else:
        start, end = raw.find("{"), raw.rfind("}")
        if start >= 0 and end > start:
            raw = raw[start : end + 1]
    try:
        parsed = json.loads(raw)
    except ValueError as exc:
        return None, "%s is not valid JSON: %s" % (label, exc)
    if not isinstance(parsed, dict):
        return None, "%s must be a JSON object" % label
    return parsed, None


def _parts(path: str) -> List[str]:
    return [part for part in re.sub(r"\[(\d+)\]", r".\1", str(path)).split(".") if part]


def _get(root: Any, path: str) -> Any:
    value = root
    for part in _parts(path):
        if isinstance(value, list):
            if not part.isdigit() or int(part) >= len(value):
                return None
            value = value[int(part)]
        elif isinstance(value, dict):
            if part not in value:
                return None
            value = value[part]
        else:
            return None
    return value


def _resolve(packet: Dict[str, Any], ref: str, dimension: str) -> Any:
    if not ref or str(ref).startswith("tickerPacket."):
        return None
    if str(ref).split(".")[0] in PACKET_PREFIXES:
        return _get(packet, ref)
    preferred = PACKET_PREFIX.get(dimension)
    order = ([preferred] if preferred else []) + [item for item in PACKET_PREFIXES if item != preferred]
    for prefix in order:
        value = _get(packet, "%s.%s" % (prefix, ref))
        if value is not None:
            return value
    return None


def _check_review(dimension: str, review: Dict[str, Any], packet: Dict[str, Any]) -> Tuple[bool, List[str]]:
    errors: List[str] = []
    if _text(review.get("dimension")).lower() != dimension:
        errors.append("dimension field must be %s" % dimension)
    for field in SCORE_FIELDS[dimension]:
        value = _num(review.get(field))
        if value is None or value != int(value) or value < 0 or value > 100:
            errors.append("%s must be 0-100" % field)
    records = review.get("evidence_records") if isinstance(review.get("evidence_records"), list) else []
    valid = 0
    for index, item in enumerate(records):
        if not isinstance(item, dict):
            continue
        ref = _text(item.get("source_ref"))
        value = item.get("source_value")
        if not ref or value is None or not _text(item.get("claim")):
            continue
        resolved = _resolve(packet, ref, dimension)
        if resolved is None or not _atomic(resolved) or not _atomic(value) or not _same(resolved, value):
            continue
        valid += 1
    if valid == 0:
        errors.append("no verified evidence")
    return (not errors), errors


def main(inputs: Any) -> Dict[str, Any]:
    if not isinstance(inputs, dict):
        inputs = {}
    packet, error = _parse(inputs.get("tickerPacket"), "tickerPacket")
    packet = packet or {}
    round_number = int(_num(inputs.get("round")) or 0)
    errors: List[str] = []
    if error:
        errors.append(error)
    for dimension in DIMENSIONS:
        key = INPUT_KEYS[dimension]
        review, parse_error = _parse(inputs.get(key), key)
        if parse_error:
            errors.append(parse_error)
            continue
        ok, review_errors = _check_review(dimension, review or {}, packet)
        if not ok:
            errors.extend("%s: %s" % (dimension, item) for item in review_errors)
    # First failed round gets one retry; the final round accepts so the outer
    # audit can reject the candidate with explicit findings.
    action = "accept" if not errors else ("continue" if round_number < 1 else "accept")
    feedback = "ok" if not errors else "; ".join(errors[:12])
    # Re-export the round's review texts through Code ports. This lets the outer
    # audit consume plain Code strings instead of traversing Loop model outputs.
    return {
        "action": action,
        "feedback": feedback,
        "round": str(round_number + 1),
        "business": _text(inputs.get("business")),
        "management": _text(inputs.get("management")),
        "financial": _text(inputs.get("financial")),
        "valuation": _text(inputs.get("valuation")),
    }

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Cloud audit Code node for the LoomLoom v4 template.

Runs after the four reviews and the model. It absorbs the local evidence audit,
narrative checks, scoring/decision logic and model self-checks so that a Market
run can return an accepted/rejected result without a local Node process.

It never rewrites numbers. Invalid evidence, unresolved refs, array/object
refs, narrative contradictions and failed model checks become findings.
"""

from __future__ import annotations

import json
import math
import re
from typing import Any, Dict, List, Optional, Tuple

DIMENSIONS = ("business", "moat", "financial", "valuation")
WEIGHTS = {
    "understandability": 0.10,
    "business_model": 0.20,
    "moat": 0.20,
    "management_capital_allocation": 0.15,
    "financial_quality": 0.20,
    "valuation_opportunity_cost": 0.15,
}
DEEP_RESEARCH_THRESHOLD = 75
WATCHLIST_THRESHOLD = 60
WEAK_SCORE_THRESHOLD = 30
HIGH_CONFIDENCE_MIN_EVIDENCE = 8
HIGH_CONFIDENCE_MAX_UNKNOWNS = 3
EXCESSIVE_REJECTED_EVIDENCE_MIN = 8
MODEL_CONTRADICTION_MOS = -0.5

PACKET_PREFIX = {
    "business": "qualitativePacket",
    "moat": "qualitativePacket",
    "financial": "financialPacket",
    "valuation": "financialPacket",
}
PACKET_PREFIXES = ("identityPacket", "financialPacket", "qualitativePacket")


def _issue(code: str, severity: str, path: str, message: str) -> Dict[str, str]:
    return {"code": code, "severity": severity, "path": path, "message": message}


def _obj(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _text(value: Any) -> str:
    return str(value if value is not None else "").strip()


def _num(value: Any) -> Optional[float]:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value) if math.isfinite(float(value)) else None
    try:
        return float(_text(value).replace(",", "").replace("$", ""))
    except ValueError:
        return None


def _atomic(value: Any) -> bool:
    return value is None or isinstance(value, (str, int, float, bool))


def _same(left: Any, right: Any) -> bool:
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return math.isclose(float(left), float(right), rel_tol=1e-6, abs_tol=1e-6)
    return json.dumps(left, sort_keys=True, ensure_ascii=False) == json.dumps(right, sort_keys=True, ensure_ascii=False)


def _parse_json(value: Any, label: str) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:
    if isinstance(value, dict):
        return value, None
    raw = _text(value)
    if not raw:
        return None, "%s is empty" % label
    fenced = re.search(r"```(?:json)?\s*(\{.*\})\s*```", raw, re.S | re.I)
    if fenced:
        raw = fenced.group(1)
    else:
        start, end = raw.find("{"), raw.rfind("}")
        if start >= 0 and end > start:
            raw = raw[start : end + 1]
    try:
        parsed = json.loads(raw)
    except ValueError as exc:
        return None, "%s is not valid JSON: %s" % (label, exc)
    if not isinstance(parsed, dict):
        return None, "%s must be a JSON object" % label
    return parsed, None


def _parts(path: str) -> List[str]:
    return [part for part in re.sub(r"\[(\d+)\]", r".\1", str(path)).split(".") if part]


def _get(root: Any, path: str) -> Any:
    value = root
    for part in _parts(path):
        if isinstance(value, list):
            if not part.isdigit():
                return None
            index = int(part)
            if index >= len(value):
                return None
            value = value[index]
        elif isinstance(value, dict):
            if part not in value:
                return None
            value = value[part]
        else:
            return None
    return value


def _resolve(packet: Dict[str, Any], ref: str, dimension: str) -> Any:
    if not ref or str(ref).startswith("tickerPacket."):
        return None
    if ref.split(".")[0] in PACKET_PREFIXES:
        return _get(packet, ref)
    preferred = PACKET_PREFIX.get(dimension)
    order = ([preferred] if preferred else []) + [p for p in PACKET_PREFIXES if p != preferred]
    for prefix in order:
        value = _get(packet, "%s.%s" % (prefix, ref))
        if value is not None:
            return value
    return None


def _score(value: Any, label: str, findings: List[Dict[str, str]]) -> int:
    number = _num(value)
    if number is None or number != int(number) or number < 0 or number > 100:
        findings.append(_issue("SCORE_INVALID", "error", label, "score must be an integer between 0 and 100"))
        return 0
    return int(number)


def _pct(value: float) -> str:
    return "%.1f%%" % (value * 100.0)


def _narrative(reviews: Dict[str, Dict[str, Any]], packet: Dict[str, Any]) -> List[Dict[str, str]]:
    findings: List[Dict[str, str]] = []
    financial = _obj(packet.get("financialPacket"))
    market = _obj(financial.get("marketSnapshot"))
    balance = _obj(financial.get("balanceSheet"))
    annual = _obj(financial.get("annualHistory"))
    recent = _obj(financial.get("quarterlyMostRecent"))
    ttm = _obj(recent.get("ttm"))
    shares = _num(market.get("sharesOutstanding")) or _num(balance.get("sharesOutstanding"))
    price = _num(market.get("price"))
    cash, debt = _num(balance.get("cash")), _num(balance.get("totalDebt"))
    if debt is None:
        debt = (_num(balance.get("shortTermDebt")) or 0.0) + (_num(balance.get("longTermDebt")) or 0.0)
    annual_fcf = _num((annual.get("freeCashFlow") or [None])[-1]) if annual.get("freeCashFlow") else None
    annual_ni = _num((annual.get("netIncome") or [None])[-1]) if annual.get("netIncome") else None
    ttm_fcf, ttm_ni = _num(ttm.get("fcf")), _num(ttm.get("netIncome"))
    pe = _num(market.get("pe"))
    net_cash = cash - debt if cash is not None and debt is not None else None

    def ratio(text: str) -> Optional[float]:
        if re.search(r"fy\s*2026|fiscal\s*(?:year\s*)?2026|10-k", text, re.I):
            return annual_fcf / annual_ni if annual_fcf is not None and annual_ni else None
        return ttm_fcf / ttm_ni if ttm_fcf is not None and ttm_ni else None

    def walk(value: Any, path: str) -> None:
        if isinstance(value, str) and value.strip():
            text = value
            current = ratio(text)
            num = r"([0-9][0-9,]*(?:\.[0-9]+)?)"
            for match in re.finditer(r"fcf\s*/\s*ni\s*(?:=|is|of|at|:)?\s*" + num + r"\s*%", text, re.I):
                stated = float(match.group(1).replace(",", "")) / 100.0
                if current is not None and abs(stated - current) > 0.06:
                    findings.append(_issue("NARRATIVE_FCF_NI_CONFLICT", "warning", path, "stated FCF/NI %s but packet implies %s" % (_pct(stated), _pct(current))))
            for match in re.finditer(r"fcf\s*/\s*ni\s*(?:=|is|of|at|:)?\s*" + num + r"\s*(?:x|times)", text, re.I):
                stated = float(match.group(1).replace(",", ""))
                if current is not None and abs(stated - current) > 0.12:
                    findings.append(_issue("NARRATIVE_FCF_NI_CONFLICT", "warning", path, "stated FCF/NI %.2fx but packet implies %.2fx" % (stated, current)))
            for match in re.finditer(r"(?:free cash flow|fcf)[^.]{0,80}?" + num + r"\s*(?:x|times)\s*(?:net income|ni)", text, re.I):
                stated = float(match.group(1).replace(",", ""))
                if current is not None and abs(stated - current) > 0.12:
                    findings.append(_issue("NARRATIVE_FCF_NI_CONFLICT", "warning", path, "stated FCF %.2fx net income but packet implies %.2fx" % (stated, current)))
            for match in re.finditer(r"(?:free cash flow|fcf)[^.]{0,100}?\b(exceeds|exceeded|above|greater than|below|less than|under)\b[^.]{0,60}?(?:net income|ni)", text, re.I):
                if current is None:
                    continue
                above = bool(re.search(r"exceed|above|greater", match.group(1), re.I))
                if (above and current < 1.0) or ((not above) and current > 1.0):
                    findings.append(_issue("NARRATIVE_FCF_NI_CONFLICT", "warning", path, "FCF direction contradicts packet ratio %.2fx" % current))
            if shares:
                for match in re.finditer(r"shares outstanding[^.]{0,50}?" + num + r"\s*(billion|b|million|m)", text, re.I):
                    stated = float(match.group(1).replace(",", "")) * (1000.0 if match.group(2).lower() in ("b", "billion") else 1.0)
                    if abs(stated - shares) / max(1.0, shares) > 0.06:
                        findings.append(_issue("NARRATIVE_SHARES_CONFLICT", "warning", path, "stated %.0fM shares but packet has %.0fM" % (stated, shares)))
            if pe:
                for match in re.finditer(r"p/e[^.]{0,30}?" + num + r"\s*x", text, re.I):
                    stated = float(match.group(1).replace(",", ""))
                    if abs(stated - pe) / max(1.0, pe) > 0.10:
                        findings.append(_issue("NARRATIVE_PE_CONFLICT", "warning", path, "stated P/E %.1fx but packet has %.1fx" % (stated, pe)))
            if net_cash is not None:
                for match in re.finditer(r"net cash[^.]{0,50}?\$?\s*(-|−)?" + num + r"\s*(billion|b|million|m)", text, re.I):
                    sign = -1.0 if match.group(1) else 1.0
                    stated = sign * float(match.group(2).replace(",", "")) * (1000.0 if match.group(3).lower() in ("b", "billion") else 1.0)
                    if net_cash < 0 and stated >= 0:
                        findings.append(_issue("NARRATIVE_NET_CASH_CONFLICT", "warning", path, "text says net cash %.0fM but packet has net debt %.0fM" % (stated, abs(net_cash))))
                    elif abs(stated - net_cash) / max(1.0, abs(net_cash)) > 0.08:
                        findings.append(_issue("NARRATIVE_NET_CASH_CONFLICT", "warning", path, "stated net cash %.0fM but packet has %.0fM" % (stated, net_cash)))
        elif isinstance(value, list):
            for index, item in enumerate(value):
                walk(item, "%s[%d]" % (path, index))
        elif isinstance(value, dict):
            for key, item in value.items():
                if key not in ("evidence_records", "falsification_conditions"):
                    walk(item, "%s.%s" % (path, key))

    for dimension, review in reviews.items():
        walk(review, "reviews.%s" % dimension)
    return findings


def _audit_evidence(reviews: Dict[str, Dict[str, Any]], packet: Dict[str, Any], findings: List[Dict[str, str]]) -> Dict[str, Any]:
    verified: List[Dict[str, Any]] = []
    rejected: List[Dict[str, Any]] = []
    by_dimension = {dimension: 0 for dimension in DIMENSIONS}
    for dimension, review in reviews.items():
        records = review.get("evidence_records") if isinstance(review.get("evidence_records"), list) else []
        for index, item in enumerate(records):
            path = "%s.evidence_records[%d]" % (dimension, index)
            if not isinstance(item, dict):
                rejected.append({"dimension": dimension, "path": path, "reason": "not an object"})
                continue
            ref = item.get("source_ref")
            value = item.get("source_value")
            if not _text(item.get("claim")) or not _text(ref) or value is None or not _text(item.get("period")) or not _text(item.get("unit")):
                findings.append(_issue("EVIDENCE_QUARANTINED", "warning", path, "evidence fields incomplete; entry dropped, not used"))
                rejected.append({"dimension": dimension, "path": path, "reason": "evidence fields incomplete"})
                continue
            if not _atomic(value):
                findings.append(_issue("EVIDENCE_QUARANTINED", "warning", path, "source_value is not atomic; entry dropped"))
                rejected.append({"dimension": dimension, "path": path, "reason": "source_value must be atomic"})
                continue
            resolved = _resolve(packet, _text(ref), dimension)
            if resolved is None:
                findings.append(_issue("EVIDENCE_QUARANTINED", "warning", path, "source_ref cannot be resolved (%s); entry dropped" % ref))
                rejected.append({"dimension": dimension, "path": path, "reason": "unresolved source_ref"})
                continue
            if not _atomic(resolved):
                findings.append(_issue("EVIDENCE_QUARANTINED", "warning", path, "source_ref is not an atomic leaf; entry dropped"))
                rejected.append({"dimension": dimension, "path": path, "reason": "non-atomic source_ref"})
                continue
            if not _same(resolved, value):
                findings.append(_issue("EVIDENCE_QUARANTINED", "warning", path, "source_value does not match the packet at %s; entry dropped" % ref))
                rejected.append({"dimension": dimension, "path": path, "reason": "source_value mismatch"})
                continue
            key = (dimension, _text(ref), json.dumps(value, sort_keys=True))
            if any((entry["dimension"], entry["source_ref"], json.dumps(entry["source_value"], sort_keys=True)) == key for entry in verified):
                continue
            verified.append({"dimension": dimension, "source_ref": _text(ref), "source_value": value})
            by_dimension[dimension] += 1
    for dimension in DIMENSIONS:
        if by_dimension.get(dimension, 0) == 0:
            findings.append(_issue("NO_VERIFIED_EVIDENCE_%s" % dimension.upper(), "error", dimension, "no verified evidence remains after quarantine"))
    return {"verified": verified, "rejected": rejected, "byDimension": by_dimension}


def _audit_trace_records(reviews: Dict[str, Dict[str, Any]], packet: Dict[str, Any], findings: List[Dict[str, str]]) -> None:
    """Validity/falsification refs must be atomic leaves too."""
    for dimension, review in reviews.items():
        for label in ("validity_basis", "falsification_conditions"):
            records = review.get(label) if isinstance(review.get(label), list) else []
            for index, item in enumerate(records):
                path = "%s.%s[%d]" % (dimension, label, index)
                if not isinstance(item, dict):
                    findings.append(_issue("TRACE_QUARANTINED", "warning", path, "record must be an object; dropped"))
                    continue
                if not _text(item.get("source_ref")) or item.get("source_value") is None:
                    findings.append(_issue("TRACE_QUARANTINED", "warning", path, "source_ref/source_value missing; dropped"))
                    continue
                resolved = _resolve(packet, _text(item.get("source_ref")), dimension)
                if resolved is None:
                    findings.append(_issue("TRACE_QUARANTINED", "warning", path, "source_ref cannot be resolved; dropped: %s" % item.get("source_ref")))
                elif not _atomic(resolved):
                    findings.append(_issue("TRACE_QUARANTINED", "warning", path, "source_ref is not an atomic leaf; dropped"))
                elif not _same(resolved, item.get("source_value")):
                    findings.append(_issue("TRACE_QUARANTINED", "warning", path, "source_value mismatch; dropped"))
                if label == "falsification_conditions" and not _text(item.get("action")):
                    findings.append(_issue("TRACE_QUARANTINED", "warning", path, "falsification action missing; dropped"))


def _artifact_path(value: Any) -> Optional[str]:
    if isinstance(value, str):
        return value
    if isinstance(value, list) and value:
        return _artifact_path(value[0])
    if isinstance(value, dict):
        for key in ("path", "file", "filePath", "filename"):
            if isinstance(value.get(key), str):
                return value[key]
    return None


def _audit_workbook(workbook: Any, findings: List[Dict[str, str]]) -> Dict[str, Any]:
    """Structural check of the xlsx artifact (sheet names/count), not cell values."""
    import zipfile

    path = _artifact_path(workbook)
    if not path:
        return {"present": False}
    try:
        with zipfile.ZipFile(path) as archive:
            names = set(archive.namelist())
            if "xl/workbook.xml" not in names:
                findings.append(_issue("WORKBOOK_INVALID", "error", "workbook", "xl/workbook.xml is missing"))
                return {"present": True, "sheets": 0}
            workbook_xml = archive.read("xl/workbook.xml").decode("utf-8", "replace")
    except Exception as exc:
        findings.append(_issue("WORKBOOK_INVALID", "error", "workbook", "cannot open workbook: %s" % exc))
        return {"present": True, "sheets": 0}
    sheets = re.findall(r'<sheet[^>]+name="([^"]+)"', workbook_xml)
    required = ("Cover", "Assumptions", "Historical", "Sensitivity", "Checks")
    missing = [name for name in required if name not in sheets]
    if missing:
        findings.append(_issue("WORKBOOK_SHEETS_MISSING", "error", "workbook", "missing sheets: %s" % ", ".join(missing)))
    if len(sheets) < 15:
        findings.append(_issue("WORKBOOK_TOO_FEW_SHEETS", "warning", "workbook", "only %d sheets; expected at least 15" % len(sheets)))
    return {"present": True, "sheets": len(sheets), "names": sheets[:40]}


def _model_audit(model: Dict[str, Any], packet: Dict[str, Any], findings: List[Dict[str, str]]) -> Dict[str, Any]:
    if not model:
        findings.append(_issue("MODEL_MISSING", "error", "model", "cloud model is required"))
        return {"verdict": "model_missing"}
    market = _obj(_obj(packet.get("financialPacket")).get("marketSnapshot"))
    if not model.get("model_ready"):
        findings.append(_issue("MODEL_NOT_READY", "error", "model", "model_ready is false"))
    for check in (model.get("modelChecks") or []):
        if isinstance(check, dict) and check.get("severity") == "error" and not check.get("passed"):
            findings.append(_issue("MODEL_CHECK_FAILED", "error", "model", "model check failed: %s" % check.get("name")))
    scenarios = _obj(model.get("scenarios"))
    for name, result in scenarios.items():
        for check in (result.get("checks") or []):
            if isinstance(check, dict) and check.get("severity") == "error" and not check.get("passed"):
                findings.append(_issue("MODEL_CHECK_FAILED", "error", "scenarios.%s" % name, "scenario check failed: %s" % check.get("name")))
    if _text(model.get("ticker")).upper() != _text(_obj(packet.get("identityPacket")).get("ticker")).upper():
        findings.append(_issue("MODEL_TICKER_MISMATCH", "error", "model.ticker", "model ticker does not match packet"))
    if _num(model.get("price")) is not None and _num(market.get("price")) is not None and not _same(model.get("price"), market.get("price")):
        findings.append(_issue("MODEL_PRICE_MISMATCH", "error", "model.price", "model price does not match packet"))
    base = _obj(scenarios.get(model.get("baseScenario") or "base"))
    summary = _obj(base.get("summary"))
    value = _num(summary.get("valuePerShare"))
    if value is not None and value <= 0:
        findings.append(_issue("MODEL_VALUE_NON_POSITIVE", "warning", "scenarios.base.summary.valuePerShare", "model value is non-positive; MOS is intentionally null"))
    mos = _num(summary.get("marginOfSafetyPct"))
    verdict = "model_incomplete" if mos is None else ("margin_of_safety_present" if mos >= 0.3 else "at_or_near_model_value" if mos >= 0 else "price_above_model_value")
    return {"verdict": verdict, "valuePerShare": value, "marginOfSafetyPct": mos, "terminalPctOfEv": _num(summary.get("terminalPctOfEv"))}


def _score_reviews(reviews: Dict[str, Dict[str, Any]], evidence: Dict[str, Any], model_audit: Dict[str, Any], findings: List[Dict[str, str]]) -> Dict[str, Any]:
    biz, moat, fin, val = reviews["business"], reviews["moat"], reviews["financial"], reviews["valuation"]
    components = {
        "understandability": _score(biz.get("understandability_score"), "business.understandability_score", findings),
        "business_model": _score(biz.get("business_model_score"), "business.business_model_score", findings),
        "moat": _score(moat.get("moat_score"), "moat.moat_score", findings),
        "management_capital_allocation": round((_score(moat.get("management_culture_score"), "moat.management_culture_score", findings) + _score(moat.get("capital_allocation_score"), "moat.capital_allocation_score", findings)) / 2),
        "financial_quality": _score(fin.get("financial_quality_score"), "financial.financial_quality_score", findings),
        "valuation_opportunity_cost": round((_score(val.get("valuation_score"), "valuation.valuation_score", findings) + _score(val.get("margin_of_safety_score"), "valuation.margin_of_safety_score", findings)) / 2),
    }
    veto: List[str] = []
    if biz.get("circle_of_competence") == "fail":
        veto.append("circle_of_competence_fail")
    for dimension in DIMENSIONS:
        if evidence["byDimension"].get(dimension, 0) == 0:
            veto.append("missing_verified_evidence_%s" % dimension)
    if (fin.get("survival_risks") or []) and _num(fin.get("balance_sheet_score")) is not None and float(fin["balance_sheet_score"]) < WEAK_SCORE_THRESHOLD:
        veto.append("survival_risk_with_weak_balance_sheet")
    if (moat.get("governance_red_flags") or []) and components["management_capital_allocation"] < WEAK_SCORE_THRESHOLD:
        veto.append("governance_red_flags_with_weak_management_score")
    if (fin.get("accounting_red_flags") or []) and components["financial_quality"] < WEAK_SCORE_THRESHOLD:
        veto.append("accounting_red_flags_with_weak_financial_score")
    if _num(val.get("margin_of_safety_score")) is not None and float(val["margin_of_safety_score"]) < WEAK_SCORE_THRESHOLD:
        veto.append("insufficient_margin_of_safety")
    if val.get("judgment_state") == "evidence_insufficient":
        veto.append("evidence_insufficient_for_valuation_anchor")
    if val.get("judgment_state") == "insufficient_margin_of_safety":
        veto.append("insufficient_margin_of_safety_verdict")
    total_evidence = len(evidence["verified"]) + len(evidence["rejected"])
    rejection_threshold = max(EXCESSIVE_REJECTED_EVIDENCE_MIN, int(math.ceil(total_evidence * 0.25)))
    if len(evidence["rejected"]) >= rejection_threshold:
        veto.append("excessive_rejected_evidence")
    if model_audit.get("verdict") == "model_incomplete":
        pass  # warning already emitted; a negative model is not a veto.
    overall = round(sum(components[key] * WEIGHTS[key] for key in WEIGHTS))
    unknowns = []
    for dimension in DIMENSIONS:
        for item in (reviews[dimension].get("unknowns") or []):
            text = _text(item)
            if text:
                unknowns.append(text)
    unknowns = list(dict.fromkeys(unknowns))
    unique_veto = list(dict.fromkeys(veto))
    audit_status = "fail" if "excessive_rejected_evidence" in unique_veto else "vetoed" if unique_veto else "warn" if evidence["rejected"] or len(unknowns) > HIGH_CONFIDENCE_MAX_UNKNOWNS else "pass"
    confidence = "low" if unique_veto else "high" if len(evidence["verified"]) >= HIGH_CONFIDENCE_MIN_EVIDENCE and len(unknowns) <= HIGH_CONFIDENCE_MAX_UNKNOWNS else "medium"
    decision = "pass" if unique_veto else "watchlist" if val.get("judgment_state") == "evidence_thin" or biz.get("circle_of_competence") == "uncertain" else "deep_research" if overall >= DEEP_RESEARCH_THRESHOLD else "watchlist" if overall >= WATCHLIST_THRESHOLD else "pass"
    return {"components": components, "overall_score": overall, "veto_items": unique_veto, "audit_status": audit_status, "confidence": confidence, "decision": decision, "unknowns": unknowns}


def audit(inputs: Dict[str, Any]) -> Dict[str, Any]:
    findings: List[Dict[str, str]] = []
    packet, error = _parse_json(inputs.get("tickerPacket"), "tickerPacket")
    if error:
        return {"accepted": False, "findings": [_issue("PACKET_NOT_JSON", "error", "tickerPacket", error)], "audit": {}}
    packet = packet or {}
    reviews: Dict[str, Dict[str, Any]] = {}
    for dimension in DIMENSIONS:
        input_key = "management" if dimension == "moat" else dimension
        review, error = _parse_json(inputs.get(input_key), input_key)
        if error:
            findings.append(_issue("REVIEW_NOT_JSON", "error", dimension, error))
            reviews[dimension] = {}
        else:
            reviews[dimension] = review or {}
            if _text(review.get("dimension")) and _text(review.get("dimension")).lower() != dimension:
                findings.append(_issue("REVIEW_DIMENSION_MISMATCH", "error", dimension, "dimension field does not match %s" % dimension))
    evidence = _audit_evidence(reviews, packet, findings)
    _audit_trace_records(reviews, packet, findings)
    for dimension in DIMENSIONS:
        if not reviews[dimension]:
            findings.append(_issue("REVIEW_MISSING", "error", dimension, "review is missing or invalid"))
    model = inputs.get("model") if isinstance(inputs.get("model"), dict) else {}
    model_audit = _model_audit(model, packet, findings)
    workbook_audit = _audit_workbook(inputs.get("workbook"), findings)
    findings.extend(_narrative(reviews, packet))
    scores = _score_reviews(reviews, evidence, model_audit, findings)
    for veto in scores["veto_items"]:
        findings.append(_issue("VETO_%s" % veto.upper(), "error", "audit", "audit veto: %s" % veto))
    hard_errors = [item for item in findings if item["severity"] == "error"]
    accepted = not hard_errors and not scores["veto_items"]
    audit_doc = {
        "schemaVersion": "loomloom-cloud-audit/v1",
        "ticker": _text(_obj(packet.get("identityPacket")).get("ticker")).upper(),
        "accepted": accepted,
        "decision": scores["decision"],
        "overall_score": scores["overall_score"],
        "component_scores": scores["components"],
        "confidence": scores["confidence"],
        "audit_status": scores["audit_status"],
        "veto_items": scores["veto_items"],
        "unknowns": scores["unknowns"],
        "evidence": {"verified": len(evidence["verified"]), "rejected": len(evidence["rejected"]), "byDimension": evidence["byDimension"]},
        "rejected_evidence": evidence["rejected"],
        "narrative_findings": [item for item in findings if item["code"].startswith("NARRATIVE_")],
        "model": model_audit,
        "workbook": workbook_audit,
        "review_summaries": {dimension: _text(reviews[dimension].get("summary")) for dimension in DIMENSIONS},
        "findings": findings,
    }
    return {"accepted": accepted, "findings": findings, "audit": audit_doc, "model": model}


def main(inputs: Any) -> Dict[str, Any]:
    if not isinstance(inputs, dict):
        inputs = {}
    return audit(inputs)


if __name__ == "__main__":
    import sys

    print(json.dumps(main(json.load(sys.stdin)), ensure_ascii=False, indent=2))

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Cloud report Code node for the LoomLoom v4 template.

Consumes the cloud audit and model and writes a Markdown artifact. It is gated
on audit.accepted, so a rejected run never produces a report that looks clean.
"""

from __future__ import annotations

import json
from typing import Any, Dict, List, Optional

REPORT_PATH = "report.md"


def _obj(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _text(value: Any) -> str:
    return str(value if value is not None else "").strip()


def _num(value: Any) -> Optional[float]:
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value).replace(",", "").replace("$", ""))
    except ValueError:
        return None


def _money(value: Any) -> str:
    number = _num(value)
    return "—" if number is None else "{:,.2f}".format(number)


def _pct(value: Any) -> str:
    number = _num(value)
    return "—" if number is None else "{:.2f}%".format(number * 100.0)


def _cell(value: Any) -> str:
    return _text(value).replace("|", "\\|").replace("\n", " ")


def _list(items: Any, empty: str = "—") -> str:
    values = [_text(item) for item in items] if isinstance(items, list) else []
    values = [value for value in values if value]
    return "\n".join("- " + value for value in values) if values else "- " + empty


def _dimensions(value: Any) -> str:
    if isinstance(value, dict) and value:
        return "\n".join("- %s: %s" % (key, count) for key, count in value.items())
    return "- no dimension counts"


def _scenario_table(model: Dict[str, Any]) -> str:
    lines = ["| Scenario | Value / share | Equity value | EV | MOS |", "|---|---:|---:|---:|---:|"]
    scenarios = _obj(model.get("scenarios"))
    for name, result in scenarios.items():
        summary = _obj(result.get("summary"))
        lines.append("| %s | %s | %s | %s | %s |" % (_cell(result.get("label") or name), _money(summary.get("valuePerShare")), _money(summary.get("equityValue")), _money(summary.get("enterpriseValue")), _pct(summary.get("marginOfSafetyPct"))))
    return "\n".join(lines)


def render(inputs: Dict[str, Any]) -> str:
    audit = _obj(inputs.get("audit"))
    model = _obj(inputs.get("model"))
    packet, _ = {}, None
    try:
        packet = json.loads(_text(inputs.get("tickerPacket"))) if inputs.get("tickerPacket") else {}
    except ValueError:
        packet = {}
    identity = _obj(packet.get("identityPacket"))
    market = _obj(_obj(packet.get("financialPacket")).get("marketSnapshot"))
    findings = audit.get("findings") if isinstance(audit.get("findings"), list) else []
    errors = [item for item in findings if _obj(item).get("severity") == "error"]
    warnings = [item for item in findings if _obj(item).get("severity") == "warning"]
    ticker = _text(audit.get("ticker")) or _text(identity.get("ticker"))
    lines = [
        "# %s | Cloud Research Report" % (ticker or "US equity"),
        "",
        "> Generated by the LoomLoom v4 cloud pipeline. Research aid only; not investment advice, target price, position size, or buy/sell instruction.",
        "",
        "## Batch summary",
        "",
        "- Cloud audit: **%s**" % ("accepted" if audit.get("accepted") else "rejected"),
        "- Decision tier: %s" % (_text(audit.get("decision")) or "—"),
        "- Overall score: %s/100; confidence: %s" % (_text(audit.get("overall_score")) or "—", _text(audit.get("confidence")) or "—"),
        "- Audit status: %s" % (_text(audit.get("audit_status")) or "—"),
        "- Errors / warnings: %d / %d" % (len(errors), len(warnings)),
        "",
        "| Ticker | Price | Price as of | Model value/share | Model MOS | Evidence |",
        "|---|---:|---|---:|---:|---:|",
        "| %s | %s | %s | %s | %s | %s verified / %s rejected |" % (
            _cell(ticker), _money(market.get("price")), _cell(market.get("asOf")),
            _money(_obj(audit.get("model")).get("valuePerShare")),
            _pct(_obj(audit.get("model")).get("marginOfSafetyPct")),
            _text(_obj(audit.get("evidence")).get("verified")),
            _text(_obj(audit.get("evidence")).get("rejected")),
        ),
        "",
        "## Investment model",
        "",
        "| Scenario | Value / share | Equity value | EV | MOS |",
        "|---|---:|---:|---:|---:|",
    ]
    scenarios = _obj(model.get("scenarios"))
    for name, result in scenarios.items():
        summary = _obj(result.get("summary"))
        lines.append("| %s | %s | %s | %s | %s |" % (_cell(result.get("label") or name), _money(summary.get("valuePerShare")), _money(summary.get("equityValue")), _money(summary.get("enterpriseValue")), _pct(summary.get("marginOfSafetyPct"))))
    base = _obj(scenarios.get(model.get("baseScenario") or "base"))
    summary = _obj(base.get("summary"))
    lines.extend([
        "",
        "- Model status: %s; engine: %s; units: %s" % ("ready" if model.get("model_ready") else "not ready", _text(model.get("engineVersion")), _text(model.get("units"))),
        "- Base value/share: %s; price: %s; MOS: %s" % (_money(summary.get("valuePerShare")), _money(summary.get("price")), _pct(summary.get("marginOfSafetyPct"))),
        "- Enterprise value: %s; equity value: %s; net debt: %s" % (_money(summary.get("enterpriseValue")), _money(summary.get("equityValue")), _money(summary.get("netDebt"))),
        "- Terminal value: %s of EV; reverse DCF implied growth: %s" % (_pct(summary.get("terminalPctOfEv")), _pct(_obj(model.get("reverseDcf")).get("impliedAverageRevenueGrowth"))),
        "",
        "## Evidence",
        "",
        "- Verified: %s; rejected: %s" % (_text(_obj(audit.get("evidence")).get("verified")), _text(_obj(audit.get("evidence")).get("rejected"))),
        _dimensions(_obj(audit.get("evidence")).get("byDimension")),
        "",
        "## Veto items",
        "",
        _list(audit.get("veto_items"), "none"),
        "",
        "## Findings",
        "",
    ])
    if findings:
        for item in findings:
            data = _obj(item)
            lines.append("- `%s` (%s) at `%s`: %s" % (_text(data.get("code")), _text(data.get("severity")), _text(data.get("path")), _text(data.get("message"))))
    else:
        lines.append("- none")
    lines.extend(["", "## Four-dimension summaries", ""])
    for dimension in ("business", "moat", "financial", "valuation"):
        lines.append("### %s" % dimension.title())
        lines.append("")
        lines.append(_text(_obj(audit.get("review_summaries")).get(dimension)) or "—")
        lines.append("")
    lines.extend([
        "## Unknowns",
        "",
        _list(audit.get("unknowns"), "none"),
        "",
        "## Use limits",
        "",
        "The cloud audit checks structure, evidence paths, narrative numbers, scoring and model self-checks. It does not prove that a source is true, that a contract will be delivered, or that a management judgment is correct. Model values are conditional arithmetic on the supplied assumptions.",
        "",
    ])
    return "\n".join(lines)


def main(inputs: Any) -> Dict[str, Any]:
    if not isinstance(inputs, dict):
        inputs = {}
    with open(REPORT_PATH, "w", encoding="utf-8") as handle:
        handle.write(render(inputs))
    return {"report": REPORT_PATH}


if __name__ == "__main__":
    import sys

    print(json.dumps(main(json.load(sys.stdin)), ensure_ascii=False))
